    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return int(a), int(b)
        return default

    def clamp_move(dx, dy):
        if dx > 1:
            dx = 1
        elif dx < -1:
            dx = -1
        if dy > 1:
            dy = 1
        elif dy < -1:
            dy = -1
        return [dx, dy]

    def best_step_toward(sx, sy, tx, ty):
        return clamp_move(sign(tx - sx), sign(ty - sy))

    def manhattan(a, b, c, d):
        return abs(a - c) + abs(b - d)

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"), (0, 0))
